import React from 'react';
import Accordion from '@mui/material/Accordion';
import AccordionDetails from '@mui/material/AccordionDetails';
import AccordionSummary from '@mui/material/AccordionSummary';
import Avatar from '@mui/material/Avatar';
import Box from '@mui/material/Box';
import Chip from '@mui/material/Chip';
import Stack from '@mui/material/Stack';
import Typography from '@mui/material/Typography';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import VisibilityIcon from '@mui/icons-material/Visibility';
import VisibilityOffIcon from '@mui/icons-material/VisibilityOff';

export interface ProfileFormSectionProps {
    icon: React.ReactNode;
    title: string;
    /** One-line preview of the values captured in this section. */
    summary: string;
    complete: boolean;
    visibility?: 'public' | 'private';
    /** Shows a lock in the header when the section's fields can't be edited. */
    locked?: boolean;
    expanded: boolean;
    onToggle: (expanded: boolean) => void;
    children: React.ReactNode;
}

/** Collapsible card used to break the profile form into short, scannable sections. */
export const ProfileFormSection: React.FC<ProfileFormSectionProps> = ({
    icon,
    title,
    summary,
    complete,
    visibility,
    locked = false,
    expanded,
    onToggle,
    children,
}) => (
    <Accordion
        expanded={expanded}
        onChange={(_, isExpanded) => onToggle(isExpanded)}
        disableGutters
        elevation={0}
        sx={{
            border: '1px solid',
            borderColor: expanded ? 'primary.main' : 'divider',
            borderRadius: 2,
            overflow: 'hidden',
            '&::before': { display: 'none' },
        }}
    >
        <AccordionSummary expandIcon={<ExpandMoreIcon />} sx={{ px: 2, '& .MuiAccordionSummary-content': { my: 1.25 } }}>
            <Stack direction="row" spacing={1.5} sx={{ alignItems: 'center', width: '100%', minWidth: 0 }}>
                <Avatar
                    sx={{
                        width: 36,
                        height: 36,
                        bgcolor: complete ? 'success.main' : 'action.selected',
                        color: complete ? 'success.contrastText' : 'text.secondary',
                    }}
                >
                    {icon}
                </Avatar>
                <Box sx={{ minWidth: 0, flexGrow: 1 }}>
                    <Stack direction="row" spacing={0.75} sx={{ alignItems: 'center' }}>
                        <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>{title}</Typography>
                        {complete && <CheckCircleIcon sx={{ fontSize: 16, color: 'success.main' }} />}
                        {locked && <LockOutlinedIcon titleAccess="Locked" sx={{ fontSize: 15, color: 'text.disabled' }} />}
                    </Stack>
                    {!expanded && (
                        <Typography variant="caption" color="text.secondary" noWrap sx={{ display: 'block' }}>
                            {summary}
                        </Typography>
                    )}
                </Box>
                {visibility && (
                    <Chip
                        size="small"
                        variant="outlined"
                        color={visibility === 'public' ? 'primary' : 'default'}
                        icon={visibility === 'public' ? <VisibilityIcon /> : <VisibilityOffIcon />}
                        label={visibility === 'public' ? 'Members' : 'Only me'}
                        sx={{ display: { xs: 'none', sm: 'inline-flex' }, flexShrink: 0 }}
                    />
                )}
            </Stack>
        </AccordionSummary>
        <AccordionDetails sx={{ px: 2, pt: 0, pb: 2.5 }}>{children}</AccordionDetails>
    </Accordion>
);
